/* @lc app=leetcode id=3956 lang=kotlin */ class Solution { fun layer(prev: LongArray, P: LongArray, l: Int, r: Int): LongArray = java.util.ArrayDeque<Int>().let { dq -> LongArray(prev.size) { Long.MIN_VALUE / 4 }.also { cur -> (0 until prev.size).forEach { i -> (if (i - l >= 0 && prev[i - l] > Long.MIN_VALUE / 8) (prev[i - l] - P[i - l]).let { v -> generateSequence { dq.peekLast()?.takeIf { prev[it] - P[it] <= v } }.forEach { _ -> dq.pollLast() }.let { dq.addLast(i - l) } } else Unit).let { generateSequence { dq.peekFirst()?.takeIf { it < i - r } }.forEach { _ -> dq.pollFirst() }.let { cur[i] = maxOf(if (i > 0) cur[i - 1] else Long.MIN_VALUE / 4, dq.peekFirst()?.let { prev[it] - P[it] + P[i] } ?: (Long.MIN_VALUE / 4)) } } } } } fun maximumSum(nums: IntArray, m: Int, l: Int, r: Int): Long = nums.runningFold(0L) { a, b -> a + b }.toLongArray().let { P -> (1..m).runningFold(LongArray(nums.size + 1)) { prev, _ -> layer(prev, P, l, r) }.drop(1).maxOf { it[nums.size] } } }